function fighter(x,color,face){return{x,y:0,vy:0,hp:100,energy:0,color,face,attack:null,cool:0,stun:0,block:false,walk:0}}
function resetRound(){p=fighter(410,'#d8ff78',1);e=fighter(870,'#ff725c',-1);time=60;transition=2;state='countdown';particles=[];ai=.6;keys={}}
