function hit(f,target){const a=f.attack,range=a.type==='punch'?135:a.type==='kick'?185:255;if(Math.abs(f.x-target.x)>range||Math.abs(f.y-target.y)>105||(target.x-f.x)*f.face<0)return;const blocked=target.block&&target.y===0;let damage=a.type==='punch'?9:a.type==='kick'?15:28;if(blocked)damage*=.18;target.hp=Math.max(0,target.hp-damage);target.stun=blocked?.08:.23;target.x=clamp(target.x+f.face*(blocked?8:22),70,1210);f.energy=clamp(f.energy+15,0,100);target.energy=clamp(target.energy+8,0,100);shake=blocked?2:9;sound(blocked?80:180,.15);for(let i=0;i<20;i++)particles.push({x:target.x-f.face*30,y:545-target.y,vx:(Math.random()-.5)*600,vy:(Math.random()-.6)*500,life:.25+Math.random()*.2,color:blocked?'#9adfff':f.color});}
function updateFighter(f,target,dt,move){f.face=target.x>=f.x?1:-1;f.cool=Math.max(0,f.cool-dt);f.stun=Math.max(0,f.stun-dt);if(f.stun<=0&&!f.attack&&!f.block){f.x=clamp(f.x+move*260*dt,70,1210);f.walk+=Math.abs(move)*dt*12}else f.walk=0;f.vy-=1700*dt;f.y=Math.max(0,f.y+f.vy*dt);if(!f.y)f.vy=0;if(f.attack){f.attack.t+=dt;const a=f.attack,impact=a.type==='punch'?.12:.22,duration=a.type==='punch'?.3:.48;if(a.t>=impact&&!a.hit){a.hit=true;hit(f,target)}if(a.t>duration)f.attack=null}}
function endRound(){if(state!=='fight')return;const win=p.hp===e.hp?-1:p.hp>e.hp?0:1;if(win>=0)wins[win]++;state='roundover';transition=2.4;$('announce').textContent=win===-1?'EMPATE':win===0?'ROUND GANADO':'ROUND PERDIDO';sound(win===0?500:90,.3)}
function finish(){state='over';$('modal').hidden=false;$('announce').textContent='';const won=wins[0]===2;if(won)storage.set('rift.wins.'+name.toLowerCase(),String(record()+1));$('result-label').textContent='RESULTADO FINAL · '+wins[0]+' — '+wins[1];$('result-title').textContent=won?'La arena es tuya.':'Vuelve más fuerte.';$('result-copy').textContent=won?'Victoria. Tu nombre ya forma parte de la arena.':'Bloquea los ataques de Vex y contraataca cuando baje la guardia.';$('resume').textContent='REVANCHA →'}
