function line(points,color,width=1){c.strokeStyle=color;c.lineWidth=width;c.beginPath();points.forEach((v,i)=>i?c.lineTo(...v):c.moveTo(...v));c.stroke()}function poly(points,color){c.fillStyle=color;c.beginPath();points.forEach((v,i)=>i?c.lineTo(...v):c.moveTo(...v));c.closePath();c.fill()}function ellipse(x,y,rx,ry,color){c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,7);c.fill()}
