for(const f of [p,e]){ellipse(f.x,665,65-f.y*.06,12,'#0007');ellipse(f.x,670,45,5,f.color+'13');drawFighter(f)}for(const a of particles){c.globalAlpha=clamp(a.life*3,0,1);line([[a.x,a.y],[a.x-a.vx*.025,a.y-a.vy*.025]],a.color,3)}c.globalAlpha=1;c.restore();
