function tick(now){const dt=Math.min((now-last)/1000||0,.033);last=now;if(state!=='paused'){clock+=dt;shake=Math.max(0,shake-dt*35);for(const a of particles){a.x+=a.vx*dt;a.y+=a.vy*dt;a.life-=dt}particles=particles.filter(a=>a.life>0)}if(state==='countdown'){transition-=dt;$('announce').textContent=transition>.8?'ROUND '+round:'¡LUCHA!';if(transition<=0){state='fight';$('announce').textContent=''}}else if(state==='fight'){time-=dt;p.block=!!keys.s&&p.y===0&&!p.attack;const diff=$('difficulty').value;const speed=diff==='easy'?.65:diff==='hard'?1.2:1;const distance=Math.abs(p.x-e.x);ai-=dt;e.block=e.cool<=0&&p.attack&&distance<190&&Math.sin(clock*9)>(diff==='hard'?-.35:.6);if(ai<=0){if(distance<185)attack(e,e.energy>=100?'special':Math.random()<.5?'punch':'kick');ai=(.35+Math.random()*.6)/speed}updateFighter(p,e,dt,(keys.d?1:0)-(keys.a?1:0));updateFighter(e,p,dt,distance>125?e.face*speed:distance<85?-e.face*.6:0);if(Math.abs(p.x-e.x)<65&&Math.abs(p.y-e.y)<100){const mid=(p.x+e.x)/2;p.x=clamp(mid-p.face*33,70,1210);e.x=clamp(mid+p.face*33,70,1210)}if(p.hp<=0||e.hp<=0||time<=0)endRound()}else if(state==='roundover'){transition-=dt;if(transition<=0){if(wins.some(v=>v>=2))finish();else{round++;resetRound()}}}if(!['login','ready'].includes(state)){$('hp1').style.width=p.hp+'%';$('hp2').style.width=e.hp+'%';$('energy').style.width=p.energy+'%';$('timer').textContent=String(Math.max(0,Math.ceil(time))).padStart(2,'0');$('round').textContent='ROUND '+String(round).padStart(2,'0');$('wins1').textContent='● '.repeat(wins[0])+'○ '.repeat(2-wins[0]);$('wins2').textContent='● '.repeat(wins[1])+'○ '.repeat(2-wins[1])}draw();requestAnimationFrame(tick)}
